--
-- Name: v_campaign_summary; Type: VIEW; Schema: public; Owner: adforecast
--

CREATE VIEW public.v_campaign_summary AS
 SELECT c.campaign_id,
    c.campaign_name,
    c.status,
    c.budget,
    c.currency,
    a.platform,
    count(DISTINCT u.upload_id) AS upload_count,
    count(m.metric_id) AS days_count,
    COALESCE(sum(m.cost), (0)::numeric) AS total_cost,
    COALESCE(sum(m.revenue), (0)::numeric) AS total_revenue,
        CASE
            WHEN (COALESCE(sum(m.cost), (0)::numeric) > (0)::numeric) THEN round((((sum(m.revenue) - sum(m.cost)) / sum(m.cost)) * (100)::numeric), 2)
            ELSE NULL::numeric
        END AS actual_roi,
    COALESCE(sum(m.impressions), (0)::bigint) AS total_impressions,
    COALESCE(sum(m.clicks), (0)::bigint) AS total_clicks
   FROM (((public.campaigns c
     JOIN public.ad_accounts a ON ((a.account_id = c.account_id)))
     LEFT JOIN public.uploads u ON ((u.campaign_id = c.campaign_id)))
     LEFT JOIN public.daily_metrics m ON ((m.upload_id = u.upload_id)))
  GROUP BY c.campaign_id, c.campaign_name, c.status, c.budget, c.currency, a.platform;


ALTER VIEW public.v_campaign_summary OWNER TO adforecast;

--
-- Name: v_forecast_stats; Type: VIEW; Schema: public; Owner: adforecast
--

CREATE VIEW public.v_forecast_stats AS
 SELECT c.campaign_id,
    c.campaign_name,
    count(f.forecast_id) AS forecast_count,
    max(f.started_at) AS last_forecast_at,
    latest.forecast_roi AS latest_forecast_roi,
    latest.payback_months AS latest_payback_months,
    latest.payback_probability AS latest_payback_probability
   FROM ((public.campaigns c
     LEFT JOIN public.forecasts f ON ((f.campaign_id = c.campaign_id)))
     LEFT JOIN LATERAL ( SELECT r.forecast_roi,
            r.payback_months,
            r.payback_probability
           FROM (public.forecasts f2
             JOIN public.forecast_results r ON ((r.forecast_id = f2.forecast_id)))
          WHERE ((f2.campaign_id = c.campaign_id) AND ((f2.status)::text = 'COMPLETED'::text))
          ORDER BY f2.started_at DESC
         LIMIT 1) latest ON (true))
  GROUP BY c.campaign_id, c.campaign_name, latest.forecast_roi, latest.payback_months, latest.payback_probability;


ALTER VIEW public.v_forecast_stats OWNER TO adforecast;

